import { useState } from "react";

function App() {
  const [text, setText] = useState("");
  const [cvText, setCvText] = useState("");
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const [history, setHistory] = useState([]);

  const handleExtract = async () => {
    if (!text) return;

    setLoading(true);

    try {
      const response = await fetch("http://127.0.0.1:8000/extract", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          job_description: text,
          cv: cvText,
        }),
      });

      const data = await response.json();
      setResult(data);

      setHistory((prev) => [
        { text: text.slice(0, 50) + "...", data },
        ...prev,
      ]);
    } catch (error) {
      console.error(error);
    }

    setLoading(false);
  };

  const handleFileUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const formData = new FormData();
    formData.append("file", file);

    const res = await fetch("http://127.0.0.1:8000/upload-cv", {
      method: "POST",
      body: formData,
    });

    const data = await res.json();
    setCvText(data.text);
  };

  const score = result?.score || 0;

  const getScoreMessage = () => {
    if (score >= 80) return "You're a strong match for this role";
    if (score >= 60) return "You're close — a few improvements will help";
    return "You are missing key skills for this job";
  };

  return (
    <div className="min-h-screen bg-slate-950 text-white flex">

      {/* SIDEBAR */}
      <div className="w-64 bg-slate-900 border-r border-slate-800 p-4 hidden md:block">
        <h2 className="text-lg font-semibold mb-4">History</h2>

        {history.map((item, i) => (
          <div
            key={i}
            onClick={() => setResult(item.data)}
            className="cursor-pointer p-2 bg-slate-800 hover:bg-slate-700 rounded-lg text-sm mb-2"
          >
            {item.text}
          </div>
        ))}
      </div>

      {/* MAIN */}
      <div className="flex-1 p-6">

        {/* NAVBAR */}
        <div className="flex justify-between items-center mb-6">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-xl flex items-center justify-center font-bold">
              AI
            </div>
            <span className="text-xl font-semibold">
              AI Job Match Analyzer
            </span>
          </div>

          <button className="px-4 py-2 bg-green-500 rounded-lg">
            See What’s Blocking You
          </button>
        </div>

        <div className="grid md:grid-cols-2 gap-6">

          {/* INPUT */}
          <div className="bg-slate-900 p-6 rounded-2xl border border-slate-800">

            <textarea
              className="w-full h-40 p-4 rounded-xl bg-slate-950 border border-slate-700"
              placeholder="Paste job description..."
              value={text}
              onChange={(e) => setText(e.target.value)}
            />

            <textarea
              className="w-full h-32 mt-4 p-4 rounded-xl bg-slate-950 border border-slate-700"
              placeholder="Paste your CV OR upload..."
              value={cvText}
              onChange={(e) => setCvText(e.target.value)}
            />

            <input
              type="file"
              accept=".pdf,.doc,.docx,.txt"
              onChange={handleFileUpload}
              className="mt-3"
            />

            <button
              onClick={handleExtract}
              className="w-full mt-4 py-3 rounded-xl bg-gradient-to-r from-indigo-500 to-purple-600"
            >
              {loading ? "Analyzing..." : "Analyze Job Match"}
            </button>
          </div>

          {/* RESULTS */}
          <div className="bg-slate-900 p-6 rounded-2xl border border-slate-800 space-y-6">

            {!result && (
              <p className="text-gray-500 text-center">
                Results appear here
              </p>
            )}

            {result && (
              <>
                {/* SCORE */}
                <div className="bg-slate-950 p-4 rounded-xl">
                  <p className="text-sm text-gray-400">Match Score</p>
                  <p className="text-3xl font-bold text-indigo-400">
                    {score}%
                  </p>
                  <p className="text-sm text-gray-400 mt-1">
                    {getScoreMessage()}
                  </p>

                  <p className="text-xs text-gray-500 mt-2">
    {result.explanation}
  </p>
                </div>

                {/* CORE */}
                <Section title="Core Skills" items={result.core_skills} />

                {/* ALL */}
                <Section title="All Skills" items={result.skills} />

                {/* MISSING (PARTIAL REVEAL) */}
                <div>
                  <h3 className="text-lg mb-2">Missing Skills</h3>

                  <Section items={result.missing_skills?.slice(0, 2)} />

                  <div className="relative mt-2">
                    <div className="blur-sm">
                      <Section items={result.missing_skills?.slice(2)} />
                    </div>

                    <Overlay />
                  </div>
                </div>

                {/* ROADMAP LOCK */}
                <div>
                  <h3 className="text-lg mb-2">Your Improvement Plan</h3>

                  <div className="relative">
                    <div className="blur-sm">
                      <ul>
                        {result.missing_skills?.slice(0, 5).map((s, i) => (
                          <li key={i}>
                            Week {i + 1}: Learn {s}
                          </li>
                        ))}
                      </ul>
                    </div>

                    <Overlay />
                  </div>
                </div>

                {/* LEVEL */}
                <div className="bg-slate-950 p-4 rounded-xl">
                  <p className="text-sm text-gray-400">Level</p>
                  <p className="text-indigo-400">{result.level}</p>
                </div>
              </>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

function Section({ title, items = [] }) {
  return (
    <div>
      {title && <h3 className="mb-2">{title}</h3>}
      <div className="flex flex-wrap gap-2">
        {(items || []).map((item, i) => (
          <span key={i} className="bg-slate-700 px-2 py-1 rounded">
            {item}
          </span>
        ))}
      </div>
    </div>
  );
}

function Overlay() {
  return (
    <div className="absolute inset-0 flex flex-col items-center justify-center">
      <p className="text-sm mb-2">
        🔒 See exactly what’s missing & how to fix it
      </p>
      <button className="bg-green-500 px-4 py-2 rounded">
        Get Full Report
      </button>
    </div>
  );
}

export default App;
